<section class="form-section"><header><h2><?= esc(lang('UI.settingsSystemTab')) ?></h2></header><form id="system-settings-form" method="post" action="<?= base_url('settings/updateSystem') ?>" data-settings-form><?= csrf_field() ?><input type="hidden" name="redirect_tab" value="system"><div class="settings-system-fields">
<div class="form-field setting-timezone"><label for="setting-timezone"><?= esc(lang('TenantMisc.timezone')) ?></label><select id="setting-timezone" name="timezone" required><?php foreach(DateTimeZone::listIdentifiers() as $timezone): ?><option value="<?= esc($timezone,'attr') ?>" <?= old('timezone',$settings['timezone']??'')===$timezone?'selected':'' ?>><?= esc($timezone) ?></option><?php endforeach; ?></select><p><?= esc(lang('TenantMisc.timezoneHelp')) ?></p></div>
<?php foreach(['date_format'=>['TenantMisc.dateFormat',['Y-m-d'=>'YYYY-MM-DD','m/d/Y'=>'MM/DD/YYYY','d/m/Y'=>'DD/MM/YYYY']],'time_format'=>['TenantMisc.timeFormat',['24'=>lang('TenantMisc.hour24'),'12'=>lang('TenantMisc.hour12')]],'ui_language'=>['Studio.interfaceLanguage',['en'=>'English','ar'=>'العربية']]] as $name=>[$label,$options]): ?><div class="form-field"><label for="setting-<?= $name ?>"><?= esc(lang($label)) ?></label><select id="setting-<?= $name ?>" name="<?= $name ?>" required><?php foreach($options as $key=>$value): ?><option value="<?= esc($key,'attr') ?>" <?= (string)old($name,$settings[$name]??'')===(string)$key?'selected':'' ?>><?= esc($value) ?></option><?php endforeach; ?></select></div><?php endforeach; ?></div><footer class="settings-save"><button type="submit" class="button primary" <?= $settingsEdit?'':'disabled' ?>><?= esc(lang('UI.settingsSaveChanges')) ?></button></footer></form></section>
<section class="settings-information"><h2><?= esc(lang('Studio.themeFuture')) ?></h2><p><?= esc(lang('Studio.themeFutureHelp')) ?></p></section>
